use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/tripling-formation176";fn r(s:impl AsRef<Path>)->PathBuf{Path::new(R).join(s)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}fn pin(p:&mut BTreeMap<String,String>,f:impl AsRef<Path>){p.insert(f.as_ref().display().to_string(),hash(&f));}
fn env()->Value{json!({"RAYON_NUM_THREADS":"1","MALLOC_ARENA_MAX":"32","MALLOC_MMAP_THRESHOLD_":"1073741824","MALLOC_TRIM_THRESHOLD_":"-1","ZOPRO_CPU_G2_PREFIX_RECORDS":"1","ZOPRO_CPU_DIRECT":"1","ZOPRO_CPU_CANONICAL_BATCH":"1","ZOPRO_CPU_VECTOR_INVERSE":"1","ZOPRO_CPU_G1_SCRATCH_STORE":"2","ZOPRO_CPU_PACKED":"1"})}
fn context(curve:&str,mode:usize,topo:&str)->Value{let size=if mode==0{200}else if mode==1{352}else{1024};let kind=format!("{curve}-{}",if mode==2{"triple"}else{"add"});let rounds=if mode==0{8192}else if mode==1{4656}else{1600};json!({"curve":curve,"mode":mode,"kind":kind,"size":size,"rounds":rounds,"topology":topo,"name":format!("{curve}-{size}-{topo}")})}
fn step(name:&str,argv:Vec<String>,environment:Value)->Value{json!({"kind":"command","name":name,"argv":argv,"environment":environment,"timeout_seconds":900})}
fn add(c:&Value,phase:&str,block:usize,binary:&str,jobs:&mut Vec<Value>,steps:&mut Vec<Value>){let n=format!("{phase}-{block:02}-{}",c["name"].as_str().unwrap());let rounds=if phase=="preflight"{32}else{c["rounds"].as_u64().unwrap()};let mut e=env();let args=vec![binary.into(),c["kind"].as_str().unwrap().into(),c["size"].to_string(),"0".into(),c["topology"].as_str().unwrap().into(),rounds.to_string()];let argv=if phase=="profile"{e["ZOPRO_BENCH_PERF_CTL"]=json!(r("ctl"));e["ZOPRO_BENCH_PERF_ACK"]=json!(r("ack"));let mut v=vec!["sudo".into(),"-n".into(),"env".into()];for(k,vv)in e.as_object().unwrap(){v.push(format!("{k}={}",vv.as_str().unwrap()));}v.extend(["perf".into(),"record".into(),"--no-buildid-cache".into(),"-e".into(),"cycles:u".into(),"-c".into(),"16000000".into(),"--timestamp".into(),"--sample-cpu".into(),"-m".into(),"512".into(),"-o".into(),r(format!("perf/{n}.data")).display().to_string(),"--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into()]);v.extend(args);v}else{args};steps.push(step(&n,argv,e));jobs.push(json!({"name":n,"phase":phase,"block":block,"context":c,"rounds":rounds}));}
fn parse(j:&Value)->Value{let name=j["name"].as_str().unwrap();let s=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let rows=s.lines().filter_map(|l|l.strip_prefix("RESULT ")).map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),1);let v=rows[0].clone();let c=&j["context"];assert_eq!(v["kind"],c["kind"]);assert_eq!(v["size"],c["size"]);assert_eq!(v["iterations_per_worker"],j["rounds"]);assert_eq!(v["timed_allocations"],0);assert_eq!(v["internally_verified"],true);assert_eq!(v["SDK_requests"],0);let cpus=match c["topology"].as_str().unwrap(){"solo"=>vec![2],"physical16"=>(0..16).collect(),"logical32"=>(0..32).collect(),_=>panic!("topology")};assert_eq!(v["cpus"],json!(cpus));let w=v["workers"].as_array().unwrap();assert_eq!(w.len(),cpus.len());assert_eq!(v["worker_count"],cpus.len());let mut tids=BTreeSet::new();let mut elapsed=0u64;for(x,cpu)in w.iter().zip(cpus){assert_eq!(x["cpu"],cpu);assert!(tids.insert(x["tid"].as_i64().unwrap()));assert_eq!(x["digest"],v["output_sha256"]);assert_eq!(x["capacity_bytes"],v["capacity_bytes_per_worker"]);elapsed+=x["elapsed_ns"].as_u64().unwrap();}let ns=elapsed as f64/(j["rounds"].as_u64().unwrap()*w.len()as u64*c["size"].as_u64().unwrap())as f64;assert!(ns>0.);json!({"ns_per_point":ns,"raw":v})}
fn prepare(){assert_eq!(load(r("native/result.json"))["status"],"complete");assert!(!r("run-plan.json").exists());let mut pins:BTreeMap<String,String>=serde_json::from_value(load(r("native-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let tests=load(r("native/core-ON/tests.json"));assert_eq!(tests["passed_tests"].as_array().unwrap().len(),128);assert_eq!(tests["unfiltered"],true);assert!(fs::read_to_string(r("native/ark-oracles/stdout.log")).unwrap().starts_with("ARK_ORACLE_PASS"));let id=load(r("probe.json"));let binary=id["binary"].as_str().unwrap();assert_eq!(hash(binary),id["sha256"]);pin(&mut pins,binary);for(p,h)in id["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}let nm=Command::new("nm").args(["-S","--size-sort","--defined-only",binary]).output().unwrap();assert!(nm.status.success());let nm=String::from_utf8(nm.stdout).unwrap();fs::create_dir(r("codegen")).unwrap();fs::write(r("codegen/symbols.txt"),&nm).unwrap();let mut asm=Vec::new();for line in nm.lines().filter(|l|(l.contains("formation")&&l.contains("apply"))||l.contains("stream_g1_impl")||(l.contains("g2_borrowed")&&l.contains("apply"))){let fields=line.split_whitespace().collect::<Vec<_>>();if fields.len()!=4{continue;}let sym=fields[3];let out=Command::new("objdump").args(["-d","--no-show-raw-insn",&format!("--disassemble={sym}"),binary]).output().unwrap();assert!(out.status.success());let s=String::from_utf8(out.stdout).unwrap();if !s.contains("vpmadd52"){continue;}let file=format!("codegen/{}.asm",asm.len());fs::write(r(&file),&s).unwrap();asm.push(json!({"symbol":sym,"bytes":u64::from_str_radix(fields[1],16).unwrap(),"file":file,"static_IFMA_instruction_lines":s.lines().filter(|l|l.contains("vpmadd52")).count()}));}assert!(asm.iter().any(|v|v["symbol"].as_str().unwrap().contains("formation")));save(r("codegen.json"),&json!(asm));let mut jobs=Vec::new();let mut steps=Vec::new();let mut contexts=Vec::new();let mut groups=Vec::new();for curve in["g1","g2"]{for topo in["solo","physical16","logical32"]{let group=(0..3).map(|m|context(curve,m,topo)).collect::<Vec<_>>();contexts.extend(group.clone());groups.push(group);}}for c in&contexts{add(c,"preflight",0,binary,&mut jobs,&mut steps);}steps.push(step("preflight-checks",vec![r("capture-helper").display().to_string(),"preflight".into()],json!({})));for block in 0..15{let mut order=(0..6).collect::<Vec<_>>();order.rotate_left(block%6);if block%2==1{order.reverse();}let mut modes=vec![0,1,2];modes.rotate_left(block%3);if block%2==1{modes.reverse();}for g in order{for &mode in&modes{add(&groups[g][mode],"latency",block,binary,&mut jobs,&mut steps);}}}fs::create_dir(r("perf")).unwrap();for f in["ctl","ack"]{assert!(Command::new("mkfifo").arg(r(f)).status().unwrap().success());}for curve in["g1","g2"]{for mode in[0,2]{add(&context(curve,mode,"logical32"),"profile",0,binary,&mut jobs,&mut steps);}}let uid=String::from_utf8(Command::new("id").arg("-u").output().unwrap().stdout).unwrap();let gid=String::from_utf8(Command::new("id").arg("-g").output().unwrap().stdout).unwrap();for j in jobs.iter().filter(|j|j["phase"]=="profile"){let n=j["name"].as_str().unwrap();let data=r(format!("perf/{n}.data"));steps.push(step(&format!("own-{n}"),vec!["sudo".into(),"-n".into(),"chown".into(),format!("{}:{}",uid.trim(),gid.trim()),data.display().to_string()],json!({})));steps.push(step(&format!("decode-{n}"),vec!["perf".into(),"script".into(),"--header".into(),"--show-lost-events".into(),"-i".into(),data.display().to_string(),"-F".into(),"pid,tid,cpu,period,ip,sym".into()],json!({})));steps.push(step(&format!("events-{n}"),vec!["perf".into(),"evlist".into(),"-v".into(),"-i".into(),data.display().to_string()],json!({})));steps.push(step(&format!("loss-{n}"),vec![r("capture-helper").display().to_string(),"loss".into(),data.display().to_string()],json!({})));}assert_eq!(jobs.len(),292);assert_eq!(steps.len(),309);save(r("jobs.json"),&json!(jobs));save(r("contexts.json"),&json!(contexts));for f in["capture.rs","capture-helper","design.md","jobs.json","contexts.json","native/result.json","codegen.json","probe.json","finish.rs"]{pin(&mut pins,r(f));}save(r("pins.json"),&json!(pins));save(r("run-plan.json"),&json!({"version":1,"source_pins":r("pins.json"),"steps":steps}));println!("Prepared309steps/18preflight270latency4profiles;native128+ArkPASS;no SDK");}
fn preflight(){let jobs=load(r("jobs.json"));let mut n=0;for j in jobs.as_array().unwrap().iter().filter(|j|j["phase"]=="preflight"){parse(j);n+=1;}assert_eq!(n,18);println!("All18callerpreflights verify output/capacity/affinity/zero timedalloc beforelatency");}
fn loss(file:&str){let out=Command::new("perf").args(["script","-D","-i",file]).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();let bad=text.lines().filter(|l|l.contains("PERF_RECORD_LOST")||l.contains("PERF_RECORD_LOST_SAMPLES")).collect::<Vec<_>>();assert!(bad.is_empty());println!("ZERO_LOST metadata_lines={}",text.lines().count());}
fn median(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
include!("finish.rs");
fn main(){let args=std::env::args().collect::<Vec<_>>();match args[1].as_str(){"prepare"=>prepare(),"preflight"=>preflight(),"loss"=>loss(&args[2]),"finish"=>finish(),_=>panic!("mode")}}
